 void progressStyle(boolean lastFive){GradientDrawable track=roundedBox(0xff293B55,0xff293B55);GradientDrawable fill=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,lastFive?new int[]{0xff236B43,0xffA5F4A4,0xffF6A3A0,0xffB50016}:new int[]{0xff236B43,0xffA5F4A4});fill.setCornerRadius(dp(6));android.graphics.drawable.ClipDrawable clip=new android.graphics.drawable.ClipDrawable(fill,Gravity.LEFT,android.graphics.drawable.ClipDrawable.HORIZONTAL);android.graphics.drawable.LayerDrawable layers=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{track,clip});layers.setId(0,android.R.id.background);layers.setId(1,android.R.id.progress);appProgress.setProgressDrawable(layers);}
