 LinearLayout backgroundRow=new LinearLayout(this);backgroundRow.setOrientation(LinearLayout.HORIZONTAL);backgroundRow.setGravity(Gravity.CENTER_VERTICAL);backgroundRow.addView(label("위젯 배경"),new LinearLayout.LayoutParams(0,-2,1));backgroundChoice=new RadioGroup(this);backgroundChoice.setOrientation(RadioGroup.HORIZONTAL);RadioButton navy=new RadioButton(this);navy.setId(View.generateViewId());navy.setText("남색");navy.setTextColor(SOFT_TEXT);navy.setTextSize(13);RadioButton clear=new RadioButton(this);clear.setId(View.generateViewId());clearBackgroundId=clear.getId();clear.setText("투명");clear.setTextColor(SOFT_TEXT);clear.setTextSize(13);backgroundChoice.addView(navy);backgroundChoice.addView(clear);backgroundRow.addView(backgroundChoice);backgroundChoice.check(prefs.getBoolean("transparent_bg",false)?clear.getId():navy.getId());add(l,backgroundRow);
