 LinearLayout resultCard=new LinearLayout(this);resultCard.setOrientation(LinearLayout.VERTICAL);resultCard.setPadding(dp(12),dp(12),dp(12),dp(12));resultCard.setBackground(roundedBox(0xff344866,0xff344866));insuranceResult=text("",13);resultCard.addView(insuranceResult);LinearLayout resultLine=new LinearLayout(this);resultLine.setGravity(Gravity.CENTER_VERTICAL);resultLine.addView(label("예상 세후 월급"),new LinearLayout.LayoutParams(0,-2,1));insuranceNetPreview=text("",21);insuranceNetPreview.setGravity(Gravity.RIGHT);insuranceNetPreview.setTextColor(0xff00E676);insuranceNetPreview.setTypeface(android.graphics.Typeface.create("sans-serif-black",android.graphics.Typeface.BOLD));resultLine.addView(insuranceNetPreview,new LinearLayout.LayoutParams(0,-2,1.5f));resultCard.addView(resultLine);add(l,resultCard);
